(6987467, 1055342, 10785, '<td valign="top">Nice way to use the light and shadow to form your letter!</td>', 'Nice way to use the light and shadow to form your letter!', '2013-02-27 22:25:01.000000', NULL, 1),
(6987468, 1055283, 10785, '<td valign="top">Nice use of repetition here to get the point across. I think you could have possibly taken a shallower angle to get the repetition plus a better leading line to strengthen the composition a little. As shot it is a little overly horizontal across the frame.</td>', 'Nice use of repetition here to get the point across. I think you could have possibly taken a shallower angle to get the repetition plus a better leading line to strengthen the composition a little. As shot it is a little overly horizontal across the frame.', '2013-02-27 22:28:31.000000', NULL, 1),
(6987469, 1055257, 10785, '<td valign="top">That creamy bokeh makes the subject stand out nicely!! Good light and nice angle of the shot!</td>', 'That creamy bokeh makes the subject stand out nicely!! Good light and nice angle of the shot!', '2013-02-27 22:29:30.000000', NULL, 1),
(6987471, 1055115, 10785, '<td valign="top">You really did a great job exposing for the bright white of the bird. The upper spine of the bird is just barely visible in the brightest area! I''ll bet this looks super wonderful at full size!</td>', 'You really did a great job exposing for the bright white of the bird. The upper spine of the bird is just barely visible in the brightest area! I''ll bet this looks super wonderful at full size!', '2013-02-27 22:32:03.000000', NULL, 1),
(6987473, 1054454, 10785, '<td valign="top">Love the tones here and with all the detailed lines in the brick work, it looks good at this small size. Typically I would see some jaggies in there, but this is done nicely. I think the center is a little too crisply sharpened and conflicts with the blurred edges. But I do like that technique to help create the focal point.</td>', 'Love the tones here and with all the detailed lines in the brick work, it looks good at this small size. Typically I would see some jaggies in there, but this is done nicely. I think the center is a little too crisply sharpened and conflicts with the blurred edges. But I do like that technique to help create the focal point.', '2013-02-27 22:36:08.000000', NULL, 1),
